def compute(vars):
    pension_fundings = vars["v1"]
    total_obligations = vars["v2"]

    if total_obligations == 0:
        return None

    value = pension_fundings / total_obligations * 100
    return {
        "value": value,
        "trace": {
            "pension_fundings": pension_fundings,
            "total_obligations": total_obligations,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
